contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;
        c.Put{value: 0}(lockTime); if (__ESBMC_reverted()) return;
        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;
        assert(balanceAfter == balanceBefore && contractBalanceAfter == contractBalanceBefore);
    }

    receive() external payable {}
}

