pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 lockTime) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        uint256 unlockBefore;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; balanceBefore = __r1; } catch { return; }
        uint contractBalanceBefore = address(c).balance;
        try c.Put{value: 0}(lockTime) {} catch { return; }
        uint256 unlockAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balanceAfter = __r1; } catch { return; }
        uint contractBalanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore && contractBalanceAfter == contractBalanceBefore);
    }

    function testFuzz_run(uint256 lockTime) public {
        _run(lockTime);
    }

    receive() external payable {}
}
